"""Original alcohol-associated liver disease chapter."""
from qbank_authoring import question,ref,finalize
ACG=ref('ACG 2024 Alcohol-Associated Liver Disease Guideline','https://pubmed.ncbi.nlm.nih.gov/38174913/')
FULL=ref('ACG 2024 ALD Guideline: Full Text','https://pmc.ncbi.nlm.nih.gov/articles/PMC11040545/')
EAS=ref('EASL Alcohol-Related Liver Disease Guideline','https://doi.org/10.1016/j.jhep.2018.03.018')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('A patient with prolonged heavy alcohol exposure develops jaundice over three weeks. Bilirubin is 9 mg/dL, AST 180 U/L, ALT 80 U/L and the AST/ALT ratio is above 1.5. What is the most appropriate interpretation?', 'The pattern is compatible with alcohol-associated hepatitis, provided important competing causes and confounders are assessed',[
 ('The ratio alone proves the diagnosis without further assessment','AST predominance is supportive but not specific for alcohol-associated hepatitis.'),('An ALT below 100 U/L excludes clinically severe hepatitis','Severity depends on liver function and organ dysfunction, not a minimum ALT of 100.'),('A diagnosis of alcohol-associated hepatitis requires AST above 2,000 U/L','Typical clinical criteria involve more modest elevations; a massive rise suggests competing causes.')],
 'Recent jaundice and a compatible exposure/laboratory pattern establish the clinical hypothesis', '**Probable alcohol-associated hepatitis is a clinical syndrome, not merely an enzyme ratio.**', ['Review exposure duration, recent drinking, onset of jaundice and the typical modest AST/ALT elevations.','Exclude biliary obstruction, viral hepatitis, ischemia, drug injury and infection as appropriate.'], '**Assess severity after identifying the syndrome.**', ['INR, creatinine, bilirubin and the overall clinical state are more useful than AST magnitude alone.','Atypical findings may justify biopsy if the diagnosis will change high-risk treatment.'], [['Compatible pattern','Recent jaundice, alcohol exposure, AST-predominant modest rise'],['Atypical massive enzymes','Search for another/concurrent injury'],['Severity','Functional and organ assessment']], [ACG,FULL], 'clinical_scenario')
q('Which finding should most strongly prompt reconsideration of uncomplicated alcohol-associated hepatitis as the sole cause of acute injury?', 'AST 4,500 U/L after a prolonged hypotensive episode',[
 ('Bilirubin 12 mg/dL with AST 190 U/L and ALT 90 U/L','This can fit alcohol-associated hepatitis in an appropriate clinical setting.'),('Tender hepatomegaly with recent-onset jaundice','These are compatible clinical findings.'),('An AST/ALT ratio of 2 with both enzymes below 400 U/L','This is a typical supportive biochemical pattern, although not diagnostic alone.')],
 'Recognize a competing injury signature', '**Very large aminotransferase elevations after shock favor hypoxic/ischemic injury.**', ['Acetaminophen toxicity and acute viral or autoimmune injury are other important causes of massive elevations.','Alcohol-associated disease and a second injury can coexist.'], '**Do not let a known alcohol history terminate the diagnostic process.**', ['Assess perfusion, LDH, medication exposure and the enzyme trajectory.','Treat the shock and assess liver function urgently.'], [['Modest AST predominance','Compatible with alcohol-associated hepatitis'],['Massive rise after shock','Hypoxic injury concern'],['Coexisting causes','Possible and clinically important']], [ACG,FULL], 'clinical_scenario')
q('When is liver biopsy particularly useful in suspected alcohol-associated hepatitis?', 'When substantial diagnostic confounding remains and the result would alter a decision such as corticosteroid treatment',[
 ('In every typical case before any supportive care','A biopsy is not obligatory for every clinically probable presentation.'),('Only after transplantation has been completed','It can guide selected pre-treatment uncertainty.'),('To replace all assessment of infection and biliary obstruction','Biopsy does not remove those diagnostic obligations.')],
 'Use histology to resolve a management-changing uncertainty', '**Atypical enzymes, uncertain exposure or another plausible acute injury can lower clinical diagnostic confidence.**', ['A transjugular approach may be preferred when coagulopathy or ascites makes percutaneous sampling less suitable.','Histological steatohepatitis findings must be interpreted with the clinical exposure history.'], '**Do not delay essential stabilization while arranging a procedure.**', ['Treat infection, withdrawal and nutritional deficits in parallel.','Biopsy risk and likely information gain should be explicit.'], [['Typical probable syndrome','Clinical diagnosis often sufficient'],['Confounded high-stakes decision','Consider biopsy'],['Coagulopathy/ascites','Assess transjugular route']], [ACG])
q('Under the ACG 2024 guideline, which MELD result supports classifying alcohol-associated hepatitis as severe for consideration of corticosteroids?', 'MELD 26',[
 ('MELD 9','This is below the guideline severe-disease threshold used for steroid consideration.'),('MELD 12','This does not reach the stated threshold.'),('MELD 16','This remains below the MELD >20 framework for severe disease.')],
 'Select a patient group in which treatment benefit is plausible', '**MELD above 20 is used to identify severe alcohol-associated hepatitis.**', ['Severity alone is not sufficient; contraindications and diagnostic confidence must also be assessed.','The degree of severity influences the likelihood of steroid benefit and the need for transplant discussion.'], '**Use a dynamic plan rather than a one-time prescription.**', ['Assess response with Lille after treatment begins.','Very advanced multiorgan failure may change the balance of benefit and futility.'], [['MELD >20','Severe-disease treatment assessment'],['Contraindication review','Required before steroids'],['Lille','On-treatment response assessment']], [ACG,FULL])
q('A patient with probable alcohol-associated hepatitis has PT 25 seconds, control PT 13 seconds and bilirubin 10 mg/dL. What is the Maddrey discriminant function?', '65.2',[
 ('22.0','This omits the 4.6 multiplier on the PT difference.'),('125.0','This does not apply the standard equation to the PT difference.'),('35.2','This underestimates the PT component for the given values.')],
 'Use the control-adjusted prothrombin-time difference', '**mDF = 4.6 × (patient PT − control PT) + bilirubin in mg/dL.**', ['Here 4.6 × 12 + 10 = 65.2.','An mDF of at least 32 historically identifies severe disease.'], '**A prognostic score does not identify every treatment exclusion.**', ['Assess infection, renal failure, bleeding and the overall clinical situation.','MELD is also important in contemporary severity stratification.'], [['PT difference','12 seconds'],['Weighted PT component','55.2'],['Final mDF','65.2']], [EAS,FULL], 'clinical_scenario')
q('A patient with severe alcohol-associated hepatitis has no active infection, uncontrolled bleeding or other contraindication. Which is a standard corticosteroid regimen?', 'Prednisolone 40 mg daily for a planned course of about four weeks, subject to early response assessment',[
 ('Dexamethasone 40 mg weekly for six months','This is not the standard regimen for this indication.'),('Hydrocortisone 10 mg daily until AST normalizes','This is not an evidence-based equivalent treatment course.'),('Prednisolone 5 mg daily indefinitely','Low-dose indefinite treatment does not match the studied severe-hepatitis approach.')],
 'Prescribe with a predefined review point', '**Steroids can improve short-term outcomes in selected severe disease, but many patients do not respond.**', ['Use an equivalent parenteral regimen only when appropriate and according to the protocol.','Screen for infection and reassess during therapy.'], '**Stop ineffective treatment rather than completing a futile course automatically.**', ['Lille at day 4 or 7 assesses response.','Persistent severe illness may require early transplant evaluation or goals-of-care discussion.'], [['Initial regimen','Prednisolone 40 mg/day'],['Early review','Lille day 4 or 7'],['Nonresponse','Discontinue and reassess strategy']], [ACG,FULL], 'clinical_scenario')
q('After seven days of prednisolone for severe alcohol-associated hepatitis, the Lille score is 0.68. What is the appropriate steroid decision?', 'Discontinue corticosteroids because this indicates nonresponse',[
 ('Continue unchanged for six months','Prolonged treatment adds risk without evidence of benefit in a nonresponder.'),('Double the dose until AST is normal','Enzyme normalization is not the response rule and dose escalation is not the established rescue strategy.'),('Ignore Lille if the initial MELD was high','Initial severity does not negate on-treatment nonresponse.')],
 'A dynamic score prevents unnecessary immunosuppression', '**A Lille score above 0.45 identifies a group in whom corticosteroids should be stopped under the ACG framework.**', ['The model incorporates the bilirubin response along with baseline factors.','A value of 0.68 is clearly above the nonresponse threshold.'], '**Use nonresponse to trigger a broader decision.**', ['Look again for infection and other reversible complications.','Consider transplant assessment in a suitable patient rather than unproven steroid escalation.'], [['Lille ≤0.45','Response-compatible continuation assessment'],['Lille >0.45','Stop for nonresponse'],['Next step','Complication review and alternative plan']], [ACG,FULL], 'clinical_scenario')
q('What is the principal difference between MELD and Lille in alcohol-associated hepatitis?', 'MELD helps assess baseline severity, whereas Lille evaluates early treatment response',[
 ('Both are alcohol-exposure biomarkers','Neither directly measures recent ethanol exposure.'),('Lille is used only before the first steroid dose','Its defining role includes dynamic change during treatment.'),('MELD is an imaging score for steatosis','It uses laboratory measures of disease severity rather than imaging fat content.')],
 'Baseline prognosis and response prognosis are separate tasks', '**A patient can be severe at baseline and still become a steroid nonresponder.**', ['MELD informs the initial risk/benefit discussion.','Lille at day 4 or 7 helps decide whether continuing steroids is worthwhile.'], '**Combine scores with the clinical state.**', ['Infection, organ failure and treatment contraindications require direct assessment.','A score does not replace multidisciplinary judgment.'], [['MELD','Baseline severity'],['Lille','Dynamic steroid response'],['Clinical review','Contraindications and complications']], [ACG,FULL])
q('A patient with severe alcohol-associated hepatitis also has uncontrolled bacterial sepsis. What is the best initial corticosteroid approach?', 'Treat and control the infection first, then reassess steroid eligibility',[
 ('Begin steroids immediately regardless of sepsis control','Uncontrolled infection is a major contraindication.'),('Declare that any prior infection permanently prohibits all steroid treatment','Eligibility may be reconsidered after adequate control.'),('Use prophylactic antifungal therapy as a substitute for infection assessment','That does not address the bacterial sepsis or establish steroid safety.')],
 'A contraindication can be dynamic', '**Systematic infection assessment precedes steroid treatment in severe disease.**', ['Fever and leukocytosis can arise from inflammation, so obtain appropriate evidence rather than assuming either cause.','Treat the identified infection and stabilize organ function.'], '**Reassess after the reversible barrier improves.**', ['Controlled infection may permit treatment in a suitable patient.','Continue surveillance because steroids increase infectious complications.'], [['Uncontrolled sepsis','Treat first'],['Infection adequately controlled','Reassess eligibility'],['During steroids','Ongoing infection monitoring']], [ACG,EAS], 'clinical_scenario')
q('Which patient has the clearest reason to defer corticosteroids initially in severe alcohol-associated hepatitis?', 'A patient with active uncontrolled gastrointestinal bleeding and severe acute kidney injury',[
 ('A patient with resolved infection after appropriate treatment and stable organ function','A previously controlled infection does not necessarily prohibit therapy.'),('A patient with bilirubin 15 mg/dL but no other contraindication','High bilirubin can reflect the severe disease being considered for treatment.'),('A patient whose AST is 160 U/L and ALT 70 U/L','That enzyme pattern alone is not a steroid contraindication.')],
 'Identify active hazards before adding immunosuppression', '**Uncontrolled bleeding, severe renal failure and active infection are important treatment barriers.**', ['The exact decision depends on severity, reversibility and the overall clinical context.','Stabilizing a barrier can change eligibility.'], '**Manage the precipitating complications urgently.**', ['Bleeding requires standard resuscitation and hemostatic assessment.','Renal injury requires evaluation for hypovolemia, sepsis, nephrotoxins and other causes.'], [['Active uncontrolled complication','Defer and stabilize'],['Resolved reversible barrier','Reassess'],['Enzyme magnitude','Not the main contraindication criterion']], [ACG,FULL], 'clinical_scenario')
q('What is the role of IV N-acetylcysteine in severe alcohol-associated hepatitis under the ACG 2024 approach?', 'Consider a short course as an adjunct to corticosteroids in an appropriate patient',[
 ('Use it as a proven complete replacement for steroids in every eligible patient','Evidence does not establish equivalent universal monotherapy.'),('Continue it indefinitely until cirrhosis is reversed','This is not the studied short-course strategy.'),('Use it only when a positive acetaminophen assay confirms overdose','Its adjunct role in this disease is distinct from acetaminophen toxicity.')],
 'An adjunct and a replacement are different evidence claims', '**A five-day IV NAC course can be considered alongside steroids in severe disease.**', ['The main evidence concerns short-term outcomes.','It does not eliminate the need for nutrition, infection care and alcohol-use treatment.'], '**Keep the response reassessment plan.**', ['Lille still guides continuation of the steroid component.','Avoid claiming a durable cure of the underlying alcohol-associated liver disease from NAC.'], [['NAC in severe hepatitis','Short adjunct course'],['Corticosteroid response','Still reassess'],['Long-term prognosis','Requires sustained alcohol and liver care']], [ACG,FULL])
q('Which drug is not recommended as routine disease-specific therapy for severe alcohol-associated hepatitis because consistent benefit has not been demonstrated?', 'Pentoxifylline',[
 ('Prednisolone in an eligible severe-disease patient','This remains a selected short-term treatment option.'),('Thiamine in a deficient or high-risk patient','This has a separate important deficiency-prevention/treatment role.'),('An indicated antibiotic for proven infection','Infection treatment remains necessary when indicated.')],
 'Historical plausibility does not guarantee clinical efficacy', '**Pentoxifylline is not a recommended routine substitute or rescue for severe alcohol-associated hepatitis.**', ['Earlier mechanistic and small-study signals did not establish a reliable survival benefit.','A steroid contraindication does not automatically make pentoxifylline effective.'], '**Use evidence-supported supportive and specialist pathways.**', ['Treat complications and nutritional deficits.','Assess selected nonresponders for early transplant rather than cycling unsupported drugs.'], [['Pentoxifylline','No routine recommendation'],['Selected steroids','Short-term treatment option'],['Supportive care','Essential regardless of drug eligibility']], [ACG,FULL])
q('A malnourished patient with alcohol-associated hepatitis is able to use the gastrointestinal tract. Which nutrition plan is most appropriate?', 'Aim for adequate energy and approximately 1.2–1.5 g/kg/day protein, adding oral/enteral support if intake is insufficient',[
 ('Restrict protein to 0.3 g/kg/day to prevent all encephalopathy','Routine severe protein restriction worsens malnutrition and muscle loss.'),('Provide alcohol calories in place of protein-containing food','Alcohol does not provide adequate nutritional rehabilitation.'),('Use parenteral nutrition automatically despite a usable gut','Oral/enteral approaches are preferred when safe and sufficient.')],
 'Nutrition is active treatment, not an optional supplement', '**A typical energy goal is about 35 kcal/kg/day with individualized adjustment.**', ['Use dry/appropriate weight and clinical context rather than fluid-overloaded weight uncritically.','Thiamine and other deficiencies and refeeding risk require assessment.'], '**Measure actual intake.**', ['Oral supplements or enteral feeding can close a persistent deficit.','Treat nausea, withdrawal and other barriers to eating.'], [['Protein','About 1.2–1.5 g/kg/day'],['Energy','Around 35 kcal/kg/day individualized'],['Poor intake','Add oral/enteral support']], [ACG,FULL], 'clinical_scenario')
q('A patient with heavy alcohol exposure is hypoglycemic and at risk of thiamine deficiency. What is the safest immediate principle?', 'Treat hypoglycemia promptly and give parenteral thiamine as soon as possible, ideally before or with glucose',[
 ('Withhold life-saving glucose until a thiamine assay returns','A delayed assay must not postpone emergency hypoglycemia correction.'),('Give glucose for days without any vitamin assessment','Carbohydrate loading can worsen the consequences of thiamine depletion.'),('Use oral folate as a complete substitute for thiamine','These vitamins have different metabolic roles.')],
 'Treat both immediate glucose danger and deficiency risk', '**Thiamine supports oxidative carbohydrate metabolism.**', ['Suspected Wernicke encephalopathy needs a therapeutic parenteral regimen.','Refeeding can also cause phosphate, potassium and magnesium shifts.'], '**Do not turn a sequencing preference into a delay in resuscitation.**', ['Urgent dextrose should not be withheld when the patient is hypoglycemic.','Follow with nutritional and electrolyte monitoring.'], [['Hypoglycemia','Immediate correction'],['Thiamine risk','Prompt parenteral replacement'],['Refeeding','Monitor electrolytes and fluid']], [ACG,FULL], 'clinical_scenario')
q('Which alcohol-use-disorder drug is particularly problematic in established liver disease because of hepatotoxicity risk?', 'Disulfiram',[
 ('Acamprosate with appropriate renal assessment','It is largely renally handled and can be an option when kidney function permits.'),('Baclofen in a carefully selected monitored patient','It has evidence in liver disease, although sedation and renal issues matter.'),('Naltrexone in selected compensated disease after risk assessment','It can be considered in an appropriate compensated setting, with important opioid and hepatic precautions.')],
 'Choose relapse-prevention therapy for the patient’s organ function', '**Disulfiram is generally avoided in alcohol-associated liver disease.**', ['Do not extrapolate this risk equally to every AUD medication.','Compensation status, kidney function, opioid use and cognition influence alternatives.'], '**Combine medication with structured addiction care.**', ['Behavioral treatment and ongoing engagement improve the chance of sustained abstinence.','A medication decision should be revisited as organ function changes.'], [['Disulfiram','Avoid due to liver risk'],['Acamprosate','Renal suitability important'],['Baclofen/naltrexone','Selected use with context-specific precautions']], [ACG,FULL])
q('A patient with compensated alcohol-associated liver disease, preserved kidney function and no opioid use wants medication for AUD. Which statement is correct?', 'Acamprosate or naltrexone may be considered within an individualized addiction-treatment plan',[
 ('All AUD pharmacotherapy is forbidden whenever any liver disease exists','This incorrectly excludes beneficial options in selected patients.'),('Naltrexone can be started without checking opioid exposure','It can precipitate withdrawal or interfere with opioid analgesia.'),('Acamprosate requires no renal consideration','Renal function materially affects suitability and dosing.')],
 'Compensated disease permits options that require careful selection', '**The ACG framework supports selected acamprosate or naltrexone use in compensated ALD.**', ['Naltrexone is unsuitable in relevant opioid-use settings and requires hepatic context review.','Acamprosate requires renal assessment.'], '**Treat AUD as part of liver care.**', ['Discuss patient goals, adherence and adverse effects.','Severe acute hepatitis or decompensation requires a different medication risk assessment.'], [['Compensated ALD','Selected AUD medicines possible'],['Naltrexone','Check opioids and hepatic context'],['Acamprosate','Check renal function']], [ACG,FULL], 'clinical_scenario')
q('Which monitoring issue is particularly relevant when baclofen is used for AUD in a patient with liver disease?', 'Sedation and accumulation in renal impairment, with caution when encephalopathy is present',[
 ('A requirement that every patient develop jaundice before benefit occurs','Jaundice is not an efficacy endpoint.'),('Complete absence of any central nervous system effect','Baclofen can cause clinically important sedation.'),('Guaranteed protection from alcohol withdrawal seizures at any dose','It should not be assumed to replace an appropriate acute-withdrawal protocol.')],
 'A liver-compatible option still has patient-specific hazards', '**Baclofen has evidence as an AUD option in selected ALD patients.**', ['It is not free of adverse effects merely because hepatic metabolism is limited.','Renal dysfunction can increase exposure and neurotoxicity.'], '**Distinguish relapse prevention from acute withdrawal treatment.**', ['Severe withdrawal requires a monitored protocol.','New confusion must be assessed for drug effect, encephalopathy and other causes.'], [['Baclofen','Selected AUD option'],['Kidney dysfunction','Accumulation risk'],['Confusion','Reassess drug and liver causes']], [ACG,FULL])
q('A patient with severe alcohol-associated hepatitis is a steroid nonresponder and has a high short-term mortality risk. What is the appropriate transplant principle?', 'Consider early transplant evaluation in a carefully selected patient without using a fixed six-month abstinence rule as the sole criterion',[
 ('Categorically exclude every patient with less than six months of abstinence','A fixed duration alone is not an adequate modern selection framework.'),('Transplant every nonresponder without psychosocial or medical evaluation','Selection requires a rigorous multidisciplinary assessment.'),('Delay referral until the patient is too unstable for evaluation','Early discussion preserves options and avoids preventable delay.')],
 'Selection should assess likely benefit and durable recovery', '**Medical severity and psychosocial/addiction assessment are both central.**', ['Support, insight, engagement and relapse-risk factors are evaluated individually.','Early transplant is not an automatic entitlement or a blanket prohibition.'], '**Continue AUD treatment through and after the transplant pathway.**', ['Post-transplant relapse prevention is part of long-term care.','A referral can be appropriate before every complication has become irreversible.'], [['Steroid nonresponse plus high risk','Early evaluation consideration'],['Selection','Medical and psychosocial assessment'],['Abstinence duration','One factor, not the sole rule']], [ACG,ref('Evaluation of Early Versus Standard Liver Transplant for ALD','https://jamanetwork.com/journals/jamasurgery/fullarticle/2782929')], 'clinical_scenario')
q('Which factor is a major modifiable determinant of long-term prognosis after alcohol-associated hepatitis?', 'Sustained abstinence supported by effective AUD treatment',[
 ('Completing steroids despite a clearly nonresponsive Lille score','Continuing ineffective immunosuppression is not a long-term protective strategy.'),('Normalizing AST once while heavy drinking continues','A temporary enzyme result does not remove ongoing injury risk.'),('Avoiding all dietary protein','This worsens malnutrition rather than improving survival.')],
 'Short-term anti-inflammatory treatment and long-term disease control are distinct', '**Continued alcohol exposure can drive recurrent injury and decompensation.**', ['Use integrated hepatology and addiction care rather than advice alone.','Nutrition, smoking, metabolic risks and social barriers also merit attention.'], '**Make abstinence support concrete.**', ['Offer appropriate medication, behavioral treatment and follow-up.','A recurrence of use should trigger renewed treatment engagement rather than dismissal from care.'], [['Short term','Treat severe hepatitis and complications'],['Long term','Sustained abstinence and liver care'],['AUD relapse','Reengage and adjust treatment']], [ACG,EAS])
q('What does phosphatidylethanol (PEth) testing most directly assess in an ALD care pathway?', 'Recent alcohol exposure over a period of weeks, interpreted alongside history and the assay context',[
 ('The exact histological fibrosis stage','PEth is not a fibrosis measurement.'),('Current steroid responsiveness','Lille, not PEth, evaluates early steroid response.'),('The presence of hepatocellular carcinoma','PEth is not a tumor marker.')],
 'Use an exposure biomarker for an exposure question', '**PEth can complement a nonjudgmental alcohol history.**', ['Detection windows, transfusion history and laboratory interpretation can affect use.','A result does not replace the broader assessment of AUD and support needs.'], '**Avoid confusing monitoring with punishment.**', ['Use findings to guide treatment engagement and safety planning.','Liver disease staging and prognosis require separate tests.'], [['PEth','Alcohol-exposure biomarker'],['Fibrosis tests','Disease stage'],['Lille','Steroid-response prognosis']], [ACG,FULL])

